1	//! Rust port of `tests/test7.cpp` from earcut.hpp: triangulate a two-turn spiral
2	//! sampled at `2 * n` points and print the resulting triangle indices.
3	//!
4	//! Usage: `test7 [n]` — `n` defaults to 7 and is parsed with `atoi` semantics.
5	
6	// `#[path]` module declarations keep this file buildable both standalone
7	// (`rustc test7.rs`) and as the Cargo `[[bin]]` target at the package root.
8	#[path = "src/cli.rs"]
9	mod cli;
10	#[path = "src/earcut/mod.rs"]
11	mod earcut;
12	#[path = "src/spiral.rs"]
13	mod spiral;
14	
15	use std::io::Write;
16	
17	fn main() {
18	    let args: Vec<String> = std::env::args().collect();
19	
20	    let mut n: i32 = 7;
21	    if args.len() > 1 {
22	        n = cli::atoi(&args[1]);
23	    }
24	
25	    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
26	    let spiral = spiral::spiral(n);
27	
28	    polygon.push(spiral);
29	
30	    let indices = earcut::earcut(&polygon);
31	
32	    // `std::cout << idx << " "` for each index: no separator logic, no trailing
33	    // newline.
34	    let mut out = String::new();
35	    for idx in &indices {
36	        out.push_str(&idx.to_string());
37	        out.push(' ');
38	    }
39	
40	    let stdout = std::io::stdout();
41	    let mut handle = stdout.lock();
42	    // A failed write leaves `std::cout` in a bad state but still returns 0 from
43	    // main, so swallow errors rather than panicking (Rust ignores SIGPIPE, which
44	    // would otherwise turn a truncated pipe into a panic message on stderr).
45	    let _ = handle.write_all(out.as_bytes());
46	    let _ = handle.flush();
47	}
48

1	//! Command-line argument handling matching the C runtime's `std::atoi`.
2	
3	/// `std::atoi` semantics as implemented by glibc, i.e. `(int) strtol(s, NULL, 10)`:
4	///
5	/// * leading whitespace is skipped,
6	/// * an optional `+`/`-` sign is consumed,
7	/// * digits are consumed greedily and parsing stops at the first non-digit,
8	/// * input with no leading digits yields `0`,
9	/// * out-of-range values saturate at the `long` bounds and are then truncated to
10	///   `int`.
11	pub fn atoi(s: &str) -> i32 {
12	    let bytes = s.as_bytes();
13	    let mut i = 0;
14	
15	    // isspace(): space, \t, \n, \v, \f, \r
16	    while i < bytes.len() && matches!(bytes[i], b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r') {
17	        i += 1;
18	    }
19	
20	    let negative = match bytes.get(i) {
21	        Some(b'-') => {
22	            i += 1;
23	            true
24	        }
25	        Some(b'+') => {
26	            i += 1;
27	            false
28	        }
29	        _ => false,
30	    };
31	
32	    let mut acc: i64 = 0;
33	    let mut overflowed = false;
34	    while i < bytes.len() && bytes[i].is_ascii_digit() {
35	        let digit = i64::from(bytes[i] - b'0');
36	        match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
37	            Some(v) => acc = v,
38	            None => overflowed = true,
39	        }
40	        i += 1;
41	    }
42	
43	    let long_value = if overflowed {
44	        if negative {
45	            i64::MIN
46	        } else {
47	            i64::MAX
48	        }
49	    } else if negative {
50	        -acc
51	    } else {
52	        acc
53	    };
54	
55	    long_value as i32
56	}
